const { isPublished } = require('./posts');
const { permalink } = require('./permalink');
const { escapeHtml } = require('./html');
const { sitemap } = require('./sitemap');

function build(site, posts, now = Date.now()) {
  const out = {};
  for (const p of posts.filter((x) => isPublished(x, now))) {
    out[permalink(p) + 'index.html'] = '<h1>' + escapeHtml(p.title) + '</h1>\n' + p.body;
  }
  out['/sitemap.xml'] = sitemap(site, posts, now);
  return out;
}

module.exports = { build };
