const http = require('node:http');

function serve(files, port = 4000) {
  return http.createServer((req, res) => {
    const body = files[req.url] ?? files[req.url + 'index.html'];
    if (!body) { res.writeHead(404); res.end(); return; }
    res.writeHead(200);
    res.end(body + '<script>new EventSource("/__reload").onmessage = () => location.reload()</script>');
  }).listen(port);
}

module.exports = { serve };
