const { absoluteUrl, permalink } = require('./permalink');
const { isPublished } = require('./posts');

function sitemap(site, posts, now = Date.now()) {
  const urls = posts.filter((p) => isPublished(p, now)).map((p) => '  <url><loc>' + absoluteUrl(site, permalink(p)) + '</loc></url>');
  return '<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n' + urls.join('\n') + '\n</urlset>\n';
}

module.exports = { sitemap };
