// Old links are indexed and shared widely, so these URLs never change. Sites are often served under a
// path (baseUrl https://example.test/blog), so every absolute link goes through absoluteUrl().
const test = require('node:test');
const assert = require('node:assert');
const { permalink, absoluteUrl } = require('../src/permalink');

const site = { baseUrl: 'https://example.test/blog/' };

test('permalinks are /YYYY/MM/slug/', () => {
  assert.strictEqual(permalink({ slug: 'hello-world', publish_at: '2026-10-01T09:00:00Z' }), '/2026/10/hello-world/');
});

test('absolute URLs keep the base path', () => {
  assert.strictEqual(absoluteUrl(site, '/2026/10/hello-world/'), 'https://example.test/blog/2026/10/hello-world/');
});
